gHK(){return"\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u043f\u0435\u0440\u0432\u043e\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435. \u0421\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b \u0435\u0433\u043e \u0443\u0432\u0438\u0434\u044f\u0442, \u0430 \u0432\u044b \u0443\u0432\u0438\u0434\u0438\u0442\u0435, \u043a\u0442\u043e \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b."},
